CREATE TABLE IF NOT EXISTS "work_hub_devices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "friendly_name" text NOT NULL, "device_class" text NOT NULL, "capabilities" jsonb NOT NULL DEFAULT '{}'::jsonb, "revoked_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "work_hub_devices_user_org_idx" ON "work_hub_devices" ("user_id", "owner_org_type", "owner_org_id");
CREATE TABLE IF NOT EXISTS "work_hub_device_connections" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "device_id" uuid NOT NULL REFERENCES "work_hub_devices"("id") ON DELETE CASCADE, "connection_id" uuid NOT NULL, "foreground" boolean NOT NULL DEFAULT false, "microphone_permission" text NOT NULL DEFAULT 'unknown', "surface" jsonb NOT NULL DEFAULT '{}'::jsonb, "connected_at" timestamptz NOT NULL DEFAULT now(), "seen_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_device_connections_device_unique" ON "work_hub_device_connections" ("device_id", "connection_id");
CREATE INDEX IF NOT EXISTS "work_hub_device_connections_seen_idx" ON "work_hub_device_connections" ("seen_at");
CREATE TABLE IF NOT EXISTS "work_hub_workspace_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "occurrence_id" uuid REFERENCES "work_hub_meeting_occurrences"("id"), "assistant_conversation_id" integer, "version" integer NOT NULL DEFAULT 1, "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_workspace_sessions_user_org_unique" ON "work_hub_workspace_sessions" ("user_id", "owner_org_type", "owner_org_id");
CREATE TABLE IF NOT EXISTS "work_hub_audio_leases" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "occurrence_id" uuid NOT NULL REFERENCES "work_hub_meeting_occurrences"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "device_id" uuid NOT NULL REFERENCES "work_hub_devices"("id"), "generation" integer NOT NULL DEFAULT 1, "token_hash" text NOT NULL, "state" text NOT NULL DEFAULT 'active', "expires_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_audio_leases_occurrence_user_unique" ON "work_hub_audio_leases" ("occurrence_id", "user_id");
CREATE TABLE IF NOT EXISTS "work_hub_device_preferences" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "ranked_device_ids" jsonb NOT NULL DEFAULT '[]'::jsonb, "automatic_backup_device_ids" jsonb NOT NULL DEFAULT '[]'::jsonb, "learning" jsonb NOT NULL DEFAULT '{}'::jsonb, "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_device_preferences_user_org_unique" ON "work_hub_device_preferences" ("user_id", "owner_org_type", "owner_org_id");
CREATE TABLE IF NOT EXISTS "work_hub_user_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "sequence" bigserial NOT NULL, "user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "owner_org_type" text NOT NULL, "owner_org_id" integer NOT NULL, "event_type" text NOT NULL, "payload" jsonb NOT NULL DEFAULT '{}'::jsonb, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_user_events_sequence_unique" ON "work_hub_user_events" ("sequence");
CREATE INDEX IF NOT EXISTS "work_hub_user_events_user_org_sequence_idx" ON "work_hub_user_events" ("user_id", "owner_org_type", "owner_org_id", "sequence");
CREATE TABLE IF NOT EXISTS "work_hub_meeting_speak_requests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "occurrence_id" uuid NOT NULL REFERENCES "work_hub_meeting_occurrences"("id") ON DELETE CASCADE, "user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE CASCADE, "status" text NOT NULL DEFAULT 'pending', "requested_at" timestamptz NOT NULL DEFAULT now(), "resolved_at" timestamptz, "resolved_by_id" integer REFERENCES "users"("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "work_hub_meeting_speak_requests_pending_unique" ON "work_hub_meeting_speak_requests" ("occurrence_id", "user_id", "status");
ALTER TABLE "work_hub_meeting_participants" ADD COLUMN IF NOT EXISTS "host_muted_at" timestamptz;
ALTER TABLE "work_hub_meeting_participants" ADD COLUMN IF NOT EXISTS "host_muted_by_id" integer REFERENCES "users"("id");
ALTER TABLE "work_hub_meeting_participants" ADD COLUMN IF NOT EXISTS "host_mute_generation" integer NOT NULL DEFAULT 0;
ALTER TABLE "work_hub_audio_leases" ADD COLUMN IF NOT EXISTS "pending_device_id" uuid REFERENCES "work_hub_devices"("id");
ALTER TABLE "work_hub_audio_leases" ADD COLUMN IF NOT EXISTS "offer_token_hash" text;
ALTER TABLE "work_hub_audio_leases" ADD COLUMN IF NOT EXISTS "offer_expires_at" timestamptz;
